// The chapter reader's books, built from files (used by index.mjs, which writes them, and check_books.mjs, which
// proves what is committed is what the files say). A book is a folder reader/content/c<NN>/<subject>/ holding:
//   book.json   written by hand: { "id": "ncert.jesc1", "boards": ["CBSE"], "catalog": { "board": "CBSE", "chapters": { "1": "cbse.c10..." } } }
//   <key>.json  one file per chapter, from the content team
//   index.json  GENERATED by index.mjs (never edited)
//   search.json GENERATED by index.mjs: the tutor's search index of the published topics (buildSearch below)
// plus the generated reader/content/books.json, which lists every book index (the Family app reads this one).
import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

export const READER = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');
export const ROOT = path.resolve(READER, '..');
const readJson = (f) => JSON.parse(fs.readFileSync(f, 'utf8'));
const dirs = (d) => (fs.existsSync(d) ? fs.readdirSync(d, { withFileTypes: true }).filter((e) => e.isDirectory()).map((e) => e.name).sort() : []);

// Every book folder under a content root: [{ cls, subject, dir, rel, files }]. A folder counts when it holds book.json or a chapter file.
export function bookFolders(root = path.join(READER, 'content')) {
  const out = [];
  for (const c of dirs(root).filter((d) => /^c\d\d$/.test(d))) {
    for (const s of dirs(path.join(root, c))) {
      const dir = path.join(root, c, s);
      const files = fs.readdirSync(dir);
      if (files.includes('book.json') || files.some((f) => /^u\..*\.json$/.test(f))) out.push({ cls: c, subject: s, dir, rel: `${c}/${s}`, files });
    }
  }
  return out;
}

// One book's index from its folder, the lab defs (the syllabus: a planned chapter has no reader file yet) and book.json.
export function buildBook(folder, { labsRoot = path.join(ROOT, 'labs/defs') } = {}) {
  const meta = readJson(path.join(folder.dir, 'book.json'));
  const code = String(meta.id).split('.')[1];
  const defsDir = path.join(labsRoot, folder.cls, folder.subject);
  const re = new RegExp(`^u\\.${folder.cls}\\.${folder.subject}\\.${code}\\.ch\\d\\d\\.json$`);
  const catalog = (meta.catalog && meta.catalog.chapters) || {};
  const chapterDefs = (fs.existsSync(defsDir) ? fs.readdirSync(defsDir) : []).filter((f) => re.test(f)).sort();
  // A book whose book.json says "list": "built" shows only chapters that have a reader file (used for the youngest
  // classes, where a "coming soon" row means nothing to the child); other books list the whole syllabus.
  const visibleDefs = meta.list === 'built' ? chapterDefs.filter((f) => fs.existsSync(path.join(folder.dir, f))) : chapterDefs;
  const chapters = visibleDefs.map((f) => {
    const def = readJson(path.join(defsDir, f));
    const number = +f.match(/ch(\d\d)/)[1];
    const rel = `${folder.rel}/${f}`;
    const out = { key: def.chapter_key, number, title: { en: def.title, hi: def.title }, file: null, topics: 0, minutes: 0, image: null, topic_titles: [], catalog_key: catalog[number] ?? null };
    const real = path.join(folder.dir, f);
    if (fs.existsSync(real)) {
      const ch = readJson(real);
      Object.assign(out, { title: ch.title, file: rel, topics: ch.topics.length, minutes: ch.minutes || ch.topics.reduce((a, t) => a + (t.minutes || 0), 0), image: (ch.hook && ch.hook.image) || null, topic_titles: ch.topics.map((t) => t.title) });
    }
    return out;
  });
  return { id: meta.id, class: +folder.cls.slice(1), subject_id: folder.subject, boards: meta.boards, catalog_board: (meta.catalog && meta.catalog.board) || null, chapters };
}

export const serialize = (x) => JSON.stringify(x, null, 1) + '\n';

// ---- search index (C505) ---------------------------------------------------------------------------------------------
// search.json, GENERATED next to index.json: one entry per topic of every published chapter (a chapter with
// "status": "draft" is left out), for the tutor to find the topic of the child's own book that a typed question is about
// (src/lib/family/book-search.ts). Each entry has the chapter and topic names, the topic's terms (en, hi) and the plain
// text of its teaching steps in each language, capped at SEARCH_TEXT_MAX characters. No SVG, no quiz items.
export const SEARCH_TEXT_MAX = 2500;
const plainText = (s) =>
  String(s)
    .replace(/<[^>]*>/g, ' ')
    .replace(/\{\{eq:([^}]*)\}\}/g, '$1')
    .replace(/\{\{[^}]*\}\}/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();
const pair = (v) => (v && typeof v === 'object' && typeof v.en === 'string' ? { en: plainText(v.en), hi: plainText(typeof v.hi === 'string' ? v.hi : v.en) } : null);
// The bilingual strings under a step's fields, in order, skipping the drawing and the quiz.
function pairsOf(x, out = []) {
  if (Array.isArray(x)) { x.forEach((y) => pairsOf(y, out)); return out; }
  if (!x || typeof x !== 'object') return out;
  const p = pair(x);
  if (p) { out.push(p); return out; }
  for (const [k, v] of Object.entries(x)) if (!['svg', 'texts', 'alt', 'item', 'items', 'gloss', 'type', 'lab'].includes(k)) pairsOf(v, out);
  return out;
}
// The teaching steps that carry the idea, in the order the text is filled (the cap keeps the first).
const STEP_ORDER = ['keypoints', 'explain', 'misconception', 'worked', 'examtip', 'table', 'diagram', 'close'];
function capText(s) {
  if (s.length <= SEARCH_TEXT_MAX) return s;
  const cut = s.slice(0, SEARCH_TEXT_MAX);
  const space = cut.lastIndexOf(' ');
  return space > SEARCH_TEXT_MAX / 2 ? cut.slice(0, space) : cut;
}
export function searchTopic(ch, t) {
  const parts = [pair(t.short), ...(t.outcomes || []).map(pair)];
  for (const type of STEP_ORDER) {
    for (const s of (t.steps || []).filter((x) => x && x.type === type)) {
      const o = type === 'misconception' ? { right: s.right, why: s.why } : type === 'diagram' ? { caption: s.caption, notice: s.notice } : s;
      parts.push(...pairsOf(o));
    }
  }
  const ok = parts.filter((p) => p && p.en);
  const join = (lang) => capText(ok.map((p) => p[lang]).filter(Boolean).map((x) => (/[.!?।:]$/.test(x) ? x : `${x}.`)).join(' '));
  return {
    chapter_key: ch.chapter_key,
    chapter: ch.number,
    chapter_title: pair(ch.title),
    topic: t.id,
    title: pair(t.title),
    terms: (t.terms || []).map((x) => ({ en: plainText(x.en || ''), hi: plainText(x.hi || x.en || '') })).filter((x) => x.en),
    text: { en: join('en'), hi: join('hi') },
  };
}
// One book's search index from its folder: published chapters in chapter order, topics in book order.
export function buildSearch(folder, book) {
  const topics = [];
  for (const c of book.chapters) {
    if (!c.file) continue;
    const ch = readJson(path.join(folder.dir, path.basename(c.file)));
    if (ch.status === 'draft') continue;
    for (const t of ch.topics || []) topics.push(searchTopic(ch, t));
  }
  return { id: book.id, class: book.class, subject_id: book.subject_id, boards: book.boards, topics };
}
// Compact, one topic per line: small to load, readable in a diff.
export const serializeSearch = (s) => `{"id":${JSON.stringify(s.id)},"class":${s.class},"subject_id":${JSON.stringify(s.subject_id)},"boards":${JSON.stringify(s.boards)},"topics":[\n${s.topics.map((t) => JSON.stringify(t)).join(',\n')}\n]}\n`;

// Everything index.mjs writes, as { path under the content root: text }, and the books.
export function buildAll(root = path.join(READER, 'content'), opts) {
  const files = {};
  const books = [];
  for (const f of bookFolders(root)) {
    if (!f.files.includes('book.json')) continue; // check_books.mjs reports it
    const b = buildBook(f, opts);
    files[`${f.rel}/index.json`] = serialize(b);
    files[`${f.rel}/search.json`] = serializeSearch(buildSearch(f, b));
    books.push(b);
  }
  books.sort((a, b) => a.class - b.class || a.subject_id.localeCompare(b.subject_id));
  files['books.json'] = serialize({ books });
  return { files, books };
}
